const TRIGRAMS={乾:{bits:[1,1,1],sym:"☰",xt:1},兑:{bits:[1,1,0],sym:"☱",xt:2},离:{bits:[1,0,1],sym:"☲",xt:3},震:{bits:[1,0,0],sym:"☳",xt:4},巽:{bits:[0,1,1],sym:"☴",xt:5},坎:{bits:[0,1,0],sym:"☵",xt:6},艮:{bits:[0,0,1],sym:"☶",xt:7},坤:{bits:[0,0,0],sym:"☷",xt:8}},XT2NAME={1:"乾",2:"兑",3:"离",4:"震",5:"巽",6:"坎",7:"艮",8:"坤"},_ORDER=["乾","兑","离","震","巽","坎","艮","坤"],_TBL={乾:["乾为天","天泽履","天火同人","天雷无妄","天风姤","天水讼","天山遁","天地否"],兑:["泽天夬","兑为泽","泽火革","泽雷随","泽风大过","泽水困","泽山咸","泽地萃"],离:["火天大有","火泽睽","离为火","火雷噬嗑","火风鼎","火水未济","火山旅","火地晋"],震:["雷天大壮","雷泽归妹","雷火丰","震为雷","雷风恒","雷水解","雷山小过","雷地豫"],巽:["风天小畜","风泽中孚","风火家人","风雷益","巽为风","风水涣","风山渐","风地观"],坎:["水天需","水泽节","水火既济","水雷屯","水风井","坎为水","水山蹇","水地比"],艮:["山天大畜","山泽损","山火贲","山雷颐","山风蛊","山水蒙","艮为山","山地剥"],坤:["地天泰","地泽临","地火明夷","地雷复","地风升","地水师","地山谦","坤为地"]};function guaName(n,s){return _TBL[n][_ORDER.indexOf(s)]}function trigramName(n){const s=n.join("");for(const t in TRIGRAMS)if(TRIGRAMS[t].bits.join("")===s)return t;return""}function hexInfo(n){const s=trigramName(n.slice(0,3)),t=trigramName(n.slice(3,6));return{name:guaName(t,s),upper:t,lower:s,usym:TRIGRAMS[t].sym,lsym:TRIGRAMS[s].sym}}const PALACE_MAP=(function(){const n={};return["乾","坎","艮","震","巽","离","坤","兑"].forEach(t=>{const i=TRIGRAMS[t].bits,u=i.concat(i),e=[];let r=u.slice();e.push({bits:u.slice(),world:6}),r=u.slice();for(let o=1;o<=5;o++)r[o-1]=r[o-1]?0:1,e.push({bits:r.slice(),world:o});const l=e[5].bits.slice();l[3]=l[3]?0:1,e.push({bits:l.slice(),world:4});const c=l.slice();c[0]=c[0]?0:1,c[1]=c[1]?0:1,c[2]=c[2]?0:1,e.push({bits:c.slice(),world:3}),e.forEach((o,a)=>{n[o.bits.join("")]={palace:t,world:o.world,type:["本宫","一世","二世","三世","四世","五世","游魂","归魂"][a]}})}),n})();function palaceInfo(n){const s=PALACE_MAP[n.join("")]||{palace:"?",world:6,type:""};let t=s.world+3;return t>6&&(t-=6),{palace:s.palace+"宫",world:s.world,ying:t,type:s.type}}const SIX_GODS=["青龙","朱雀","勾陈","螣蛇","白虎","玄武"];function sixGods(n){let s={甲:0,乙:0,丙:1,丁:1,戊:2,己:3,庚:4,辛:4,壬:5,癸:5}[n]||0;const t=[];for(let i=0;i<6;i++)t.push(SIX_GODS[(s+i)%6]);return t}

;
const GUA_CI={乾为天:"元亨利贞",坤为地:"元亨，利牝马之贞，君子有攸往，先迷后得主，利，西南得朋，东北丧朋，安贞吉",水雷屯:"元亨利贞，勿用有攸往，利建侯",山水蒙:"亨。匪我求童蒙，童蒙求我。初筮告，再三渎，渎则不告。利贞",水天需:"有孚，光亨，贞吉，利涉大川",天水讼:"有孚，窒惕，中吉，终凶，利见大人，不利涉大川",地水师:"贞，丈人吉，无咎",水地比:"吉。原筮，元永贞，无咎。不宁方来，后夫凶",风天小畜:"亨，密云不雨，自我西郊",天泽履:"履虎尾，不咥人，亨",地天泰:"小往大来，吉亨",天地否:"否之匪人，不利君子贞，大往小来",天火同人:"同人于野，亨。利涉大川，利君子贞",火天大有:"元亨",地山谦:"亨，君子有终",雷地豫:"利建侯行师",泽雷随:"元亨利贞，无咎",山风蛊:"元亨，利涉大川。先甲三日，后甲三日",地泽临:"元亨利贞，至于八月有凶",风地观:"盥而不荐，有孚颙若",火雷噬嗑:"亨，利用狱",山火贲:"亨，小利有攸往",山地剥:"不利有攸往",地雷复:"亨。出入无疾，朋来无咎。反复其道，七日来复，利有攸往",天雷无妄:"元亨利贞。其匪正有眚，不利有攸往",山天大畜:"利贞，不家食吉，利涉大川",山雷颐:"贞吉，观颐，自求口实",泽风大过:"栋桡，利有攸往，亨",坎为水:"习坎，有孚维心亨，行有尚",离为火:"利贞，亨，畜牝牛吉",泽山咸:"亨，利贞，取女吉",雷风恒:"亨，无咎，利贞，利有攸往",天山遁:"亨，小利贞",雷天大壮:"利贞",火地晋:"康侯用锡马蕃庶，昼日三接",地火明夷:"利艰贞",风火家人:"利女贞",火泽睽:"小事吉",水山蹇:"利西南，不利东北，利见大人，贞吉",雷水解:"利西南，无所往，其来复吉，有攸往，夙吉",山泽损:"有孚，元吉，无咎，可贞，利有攸往，曷之用，二簋可用享",风雷益:"利有攸往，利涉大川",泽天夬:"扬于王庭，孚号有厉，告自邑，不利即戎，利有攸往",天风姤:"女壮，勿用取女",泽地萃:"亨，王假有庙，利见大人，亨，利贞，用大牲吉，利有攸往",地风升:"元亨，用见大人，勿恤，南征吉",泽水困:"亨，贞大人吉，无咎，有言不信",水风井:"改邑不改井，无丧无得，往来井井，汔至亦未繘井，羸其瓶，凶",泽火革:"巳日乃孚。元亨利贞，悔亡",火风鼎:"元吉，亨",震为雷:"亨。震来虩虩，笑言哑哑。震惊百里，不丧匕鬯",艮为山:"艮其背，不获其身，行其庭，不见其人，无咎",风山渐:"女归吉，利贞",雷泽归妹:"征凶，无攸利",雷火丰:"亨，王假之，勿忧宜日中",火山旅:"小亨，旅贞吉",巽为风:"小亨，利有攸往，利见大人",兑为泽:"亨，利贞",风水涣:"亨。王假有庙，利涉大川，利贞",水泽节:"亨，苦节不可贞",风泽中孚:"豚鱼吉，利涉大川，利贞",雷山小过:"亨，利贞。可小事，不可大事。飞鸟遗之音，不宜上，宜下，大吉",水火既济:"亨小，利贞，初吉终乱",火水未济:"亨，小狐汔济，濡其尾，无攸利"},GUA_TUAN={乾为天:"大哉乾元，万物资始，乃统天。云行雨施，品物流形。大明终始，六位时成，时乘六龙以御天。乾道变化，各正性命，保合大和，乃利贞。首出庶物，万国咸宁。",坤为地:"至哉坤元，万物资生，乃顺承天。坤厚载物，德合无疆。含弘光大，品物咸亨。牝马地类，行地无疆，柔顺利贞。君子攸行，先迷失道，后顺得常。西南得朋，乃与类行；东北丧朋，乃终有庆。安贞之吉，应地无疆。",水雷屯:"屯，刚柔始交而难生，动乎险中，大亨贞。雷雨之动满盈，天造草昧，宜建侯而不宁。",山水蒙:"蒙，山下有险，险而止，蒙。蒙亨，以亨行时中也。匪我求童蒙，童蒙求我，志应也。初筮告，以刚中也。再三渎，渎则不告，渎蒙也。蒙以养正，圣功也。",水天需:"需，须也，险在前也。刚健而不陷，其义不困穷矣。需，有孚，光亨贞吉，位乎天位，以正中也。利涉大川，往有功也。",天水讼:"讼，上刚下险，险而健，讼。讼有孚窒惕中吉，刚来而得中也。终凶，讼不可成也。利见大人，尚中正也。不利涉大川，入于渊也。",地水师:"师，众也；贞，正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下，而民从之，吉又何咎矣。",水地比:"比，吉也；比，辅也，下顺从也。原筮元永贞无咎，以刚中也。不宁方来，上下应也。后夫凶，其道穷也。",风天小畜:"小畜，柔得位而上下应之，曰小畜。健而巽，刚中而志行，乃亨。密云不雨，尚往也；自我西郊，施未行也。",天泽履:"履，柔履刚也。说而应乎乾，是以履虎尾，不咥人，亨。刚中正，履帝位而不疚，光明也。",地天泰:"泰，小往大来，吉亨。则是天地交而万物通也，上下交而其志同也。内阳而外阴，内健而外顺，内君子而外小人，君子道长，小人道消也。",天地否:"否之匪人，不利君子贞，大往小来。则是天地不交而万物不通也，上下不交而天下无邦也。内阴而外阳，内柔而外刚，内小人而外君子，小人道长，君子道消也。",天火同人:"同人，柔得位得中，而应乎乾，曰同人。同人曰：同人于野，亨，利涉大川，乾行也。文明以健，中正而应，君子正也。唯君子为能通天下之志。",火天大有:"大有，柔得尊位大中，而上下应之，曰大有。其德刚健而文明，应乎天而时行，是以元亨。",地山谦:"谦，亨。天道下济而光明，地道卑而上行。天道亏盈而益谦，地道变盈而流谦，鬼神害盈而福谦，人道恶盈而好谦。谦尊而光，卑而不可逾，君子之终也。",雷地豫:"豫，刚应而志行，顺以动，豫。豫顺以动，故天地如之，而况建侯行师乎？天地以顺动，故日月不过而四时不忒；圣人以顺动，则刑罚清而民服。豫之时义大矣哉！",泽雷随:"随，刚来而下柔，动而说，随。大亨贞无咎，而天下随时。随时之义大矣哉！",山风蛊:"蛊，刚上而柔下，巽而止，蛊。蛊元亨而天下治也。利涉大川，往有事也。先甲三日，后甲三日，终则有始，天行也。",地泽临:"临，刚浸而长，说而顺，刚中而应。大亨以正，天之道也。至于八月有凶，消不久也。",风地观:"大观在上，顺而巽，中正以观天下。观，盥而不荐，有孚颙若，下观而化也。观天之神道，而四时不忒；圣人以神道设教，而天下服矣。",火雷噬嗑:"颐中有物，曰噬嗑。噬嗑而亨，刚柔分，动而明，雷电合而章。柔得中而上行，虽不当位，利用狱也。",山火贲:"贲，亨，柔来而文刚，故亨；分刚上而文柔，故小利有攸往。刚柔交错，天文也；文明以止，人文也。观乎天文，以察时变；观乎人文，以化成天下。",山地剥:"剥，剥也，柔变刚也。不利有攸往，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。",地雷复:"复，亨。刚反，动而以顺行，是以出入无疾，朋来无咎。反复其道，七日来复，天行也。利有攸往，刚长也。复，其见天地之心乎？",天雷无妄:"无妄，刚自外来而为主于内，动而健，刚中而应，大亨以正，天之命也。其匪正有眚，不利有攸往，无妄之往，何之矣？天命不佑，行矣哉？",山天大畜:"大畜，刚健笃实辉光，日新其德。刚上而尚贤，能止健，大正也。不家食吉，养贤也。利涉大川，应乎天也。",山雷颐:"颐，贞吉，养正则吉也。观颐，观其所养也；自求口实，观其自养也。天地养万物，圣人养贤以及万民。颐之时大矣哉！",泽风大过:"大过，大者过也。栋桡，本末弱也。刚过而中，巽而说行，利有攸往，乃亨。大过之时大矣哉！",坎为水:"习坎，重险也。水流而不盈，行险而不失其信。维心亨，乃以刚中也。行有尚，往有功也。天险不可升也，地险山川丘陵也，王公设险以守其国。险之时用大矣哉！",离为火:"离，丽也。日月丽乎天，百谷草木丽乎土。重明以丽乎正，乃化成天下。柔丽乎中正，故亨，是以畜牝牛吉也。",泽山咸:"咸，感也。柔上而刚下，二气感应以相与。止而说，男下女，是以亨利贞，取女吉也。天地感而万物化生，圣人感人心而天下和平。观其所感，而天地万物之情可见矣。",雷风恒:"恒，久也。刚上而柔下，雷风相与，巽而动，刚柔皆应，恒。恒亨无咎利贞，久于其道也。天地之道，恒久而不已也。利有攸往，终则有始也。日月得天而能久照，四时变化而能久成，圣人久于其道而天下化成。观其所恒，而天地万物之情可见矣。",天山遁:"遁，亨，遁而亨也。刚当位而应，与时行也。小利贞，浸而长也。遁之时义大矣哉！",雷天大壮:"大壮，大者壮也。刚以动，故壮。大壮利贞，大者正也。正大而天地之情可见矣。",火地晋:"晋，进也。明出地上，顺而丽乎大明，柔进而上行，是以康侯用锡马蕃庶，昼日三接也。",地火明夷:"明入地中，明夷。内文明而外柔顺，以蒙大难，文王以之。利艰贞，晦其明也。内难而能正其志，箕子以之。",风火家人:"家人，女正位乎内，男正位乎外，男女正，天地之大义也。家人有严君焉，父母之谓也。父父，子子，兄兄，弟弟，夫夫，妇妇，而家道正；正家而天下定矣。",火泽睽:"睽，火动而上，泽动而下；二女同居，其志不同行。说而丽乎明，柔进而上行，得中而应乎刚，是以小事吉。天地睽而其事同也，男女睽而其志通也，万物睽而其事类也。睽之时用大矣哉！",水山蹇:"蹇，难也，险在前也。见险而能止，知矣哉！蹇利西南，往得中也；不利东北，其道穷也。利见大人，往有功也。当位贞吉，以正邦也。蹇之时用大矣哉！",雷水解:"解，险以动，动而免乎险，解。解利西南，往得众也。其来复吉，乃得中也。有攸往夙吉，往有功也。天地解而雷雨作，雷雨作而百果草木皆甲坼。解之时大矣哉！",山泽损:"损，损下益上，其道上行。损而有孚，元吉，无咎，可贞，利有攸往。曷之用？二簋可用享。二簋应有时，损刚益柔有时。损益盈虚，与时偕行。",风雷益:"益，损上益下，民说无疆。自上下下，其道大光。利有攸往，中正有庆。利涉大川，木道乃行。益动而巽，日进无疆。天施地生，其益无方。凡益之道，与时偕行。",泽天夬:"夬，决也，刚决柔也。健而说，决而和。扬于王庭，柔乘五刚也。孚号有厉，其危乃光也。告自邑，不利即戎，所尚乃穷也。利有攸往，刚长乃终也。",天风姤:"姤，遇也，柔遇刚也。勿用取女，不可与长也。天地相遇，品物咸章也。刚遇中正，天下大行也。姤之时义大矣哉！",泽地萃:"萃，聚也。顺以说，刚中而应，故聚也。王假有庙，致孝享也。利见大人亨，聚以正也。用大牲吉，利有攸往，顺天命也。观其所聚，而天地万物之情可见矣。",地风升:"柔以时升，巽而顺，刚中而应，是以大亨。用见大人，勿恤，有庆也。南征吉，志行也。",泽水困:"困，刚掩也。险以说，困而不失其所亨，其唯君子乎？贞大人吉，以刚中也。有言不信，尚口乃穷也。",水风井:"巽乎水而上水，井。井养而不穷也。改邑不改井，乃以刚中也。汔至亦未繘井，未有功也。羸其瓶，是以凶也。",泽火革:"革，水火相息，二女同居，其志不相得，曰革。巳日乃孚，革而信之。文明以说，大亨以正。革而当，其悔乃亡。天地革而四时成。汤武革命，顺乎天而应乎人。革之时大矣哉！",火风鼎:"鼎，象也。以木巽火，亨饪也。圣人亨以享上帝，而大亨以养圣贤。巽而耳目聪明，柔进而上行，得中而应乎刚，是以元亨。",震为雷:"震，亨。震来虩虩，恐致福也。笑言哑哑，后有则也。震惊百里，惊远而惧迩也。出可以守宗庙社稷，以为祭主也。",艮为山:"艮，止也。时止则止，时行则行，动静不失其时，其道光明。艮其止，止其所也。上下敌应，不相与也。是以不获其身，行其庭不见其人，无咎也。",风山渐:"渐之进也，女归吉也。进得位，往有功也。进以正，可以正邦也。其位，刚得中也。止而巽，动不穷也。",雷泽归妹:"归妹，天地之大义也。天地不交而万物不兴。归妹，人之终始也。说以动，所归妹也。征凶，位不当也。无攸利，柔乘刚也。",雷火丰:"丰，大也。明以动，故丰。王假之，尚大也。勿忧宜日中，宜照天下也。日中则昃，月盈则食，天地盈虚，与时消息，而况于人乎？况于鬼神乎？",火山旅:"旅，小亨，柔得中乎外而顺乎刚，止而丽乎明，是以小亨旅贞吉也。旅之时义大矣哉！",巽为风:"重巽以申命。刚巽乎中正而志行，柔皆顺乎刚，是以小亨，利有攸往，利见大人。",兑为泽:"兑，说也。刚中而柔外，说以利贞，是以顺乎天而应乎人。说以先民，民忘其劳；说以犯难，民忘其死。说之大，民劝矣哉！",风水涣:"涣，亨。刚来而不穷，柔得位乎外而上同。王假有庙，王乃在中也。利涉大川，乘木有功也。",水泽节:"节，亨。刚柔分而刚得中。苦节不可贞，其道穷也。说以行险，当位以节，中正以通。天地节而四时成。节以制度，不伤财，不害民。",风泽中孚:"中孚，柔在内而刚得中，说而巽，孚乃化邦也。豚鱼吉，信及豚鱼也。利涉大川，乘木舟虚也。中孚以利贞，乃应乎天也。",雷山小过:"小过，小者过而亨也。过以利贞，与时行也。柔得中，是以小事吉也。刚失位而不中，是以不可大事也。有飞鸟之象焉。飞鸟遗之音，不宜上宜下，大吉，上逆而下顺也。",水火既济:"既济，亨，小者亨也。利贞，刚柔正而位当也。初吉，柔得中也。终止则乱，其道穷也。",火水未济:"未济，亨，柔得中也。小狐汔济，未出中也。濡其尾，无攸利，不续终也。虽不当位，刚柔应也。"},GUA_DAXIANG={乾为天:"天行健，君子以自强不息。",坤为地:"地势坤，君子以厚德载物。",水雷屯:"云雷屯，君子以经纶。",山水蒙:"山下出泉，蒙。君子以果行育德。",水天需:"云上于天，需。君子以饮食宴乐。",天水讼:"天与水违行，讼。君子以作事谋始。",地水师:"地中有水，师。君子以容民畜众。",水地比:"地上有水，比。先王以建万国，亲诸侯。",风天小畜:"风行天上，小畜。君子以懿文德。",天泽履:"上天下泽，履。君子以辨上下，定民志。",地天泰:"天地交，泰。后以财成天地之道，辅相天地之宜，以左右民。",天地否:"天地不交，否。君子以俭德辟难，不可荣以禄。",天火同人:"天与火，同人。君子以类族辨物。",火天大有:"火在天上，大有。君子以遏恶扬善，顺天休命。",地山谦:"地中有山，谦。君子以裒多益寡，称物平施。",雷地豫:"雷出地奋，豫。先王以作乐崇德，殷荐之上帝，以配祖考。",泽雷随:"泽中有雷，随。君子以向晦入宴息。",山风蛊:"山下有风，蛊。君子以振民育德。",地泽临:"泽上有地，临。君子以教思无穷，容保民无疆。",风地观:"风行地上，观。先王以省方观民设教。",火雷噬嗑:"雷电，噬嗑。先王以明罚敕法。",山火贲:"山下有火，贲。君子以明庶政，无敢折狱。",山地剥:"山附于地，剥。上以厚下安宅。",地雷复:"雷在地中，复。先王以至日闭关，商旅不行，后不省方。",天雷无妄:"天下雷行，物与无妄。先王以茂对时育万物。",山天大畜:"天在山中，大畜。君子以多识前言往行，以畜其德。",山雷颐:"山下有雷，颐。君子以慎言语，节饮食。",泽风大过:"泽灭木，大过。君子以独立不惧，遁世无闷。",坎为水:"水洊至，习坎。君子以常德行，习教事。",离为火:"明两作，离。大人以继明照于四方。",泽山咸:"山上有泽，咸。君子以虚受人。",雷风恒:"雷风，恒。君子以立不易方。",天山遁:"天下有山，遁。君子以远小人，不恶而严。",雷天大壮:"雷在天上，大壮。君子以非礼弗履。",火地晋:"明出地上，晋。君子以自昭明德。",地火明夷:"明入地中，明夷。君子以莅众，用晦而明。",风火家人:"风自火出，家人。君子以言有物而行有恒。",火泽睽:"上火下泽，睽。君子以同而异。",水山蹇:"山上有水，蹇。君子以反身修德。",雷水解:"雷雨作，解。君子以赦过宥罪。",山泽损:"山下有泽，损。君子以惩忿窒欲。",风雷益:"风雷，益。君子以见善则迁，有过则改。",泽天夬:"泽上于天，夬。君子以施禄及下，居德则忌。",天风姤:"天下有风，姤。后以施命诰四方。",泽地萃:"泽上于地，萃。君子以除戎器，戒不虞。",地风升:"地中生木，升。君子以顺德，积小以高大。",泽水困:"泽无水，困。君子以致命遂志。",水风井:"木上有水，井。君子以劳民劝相。",泽火革:"泽中有火，革。君子以治历明时。",火风鼎:"木上有火，鼎。君子以正位凝命。",震为雷:"洊雷，震。君子以恐惧修省。",艮为山:"兼山，艮。君子以思不出其位。",风山渐:"山上有木，渐。君子以居贤德善俗。",雷泽归妹:"泽上有雷，归妹。君子以永终知敝。",雷火丰:"雷电皆至，丰。君子以折狱致刑。",火山旅:"山上有火，旅。君子以明慎用刑而不留狱。",巽为风:"随风，巽。君子以申命行事。",兑为泽:"丽泽，兑。君子以朋友讲习。",风水涣:"风行水上，涣。先王以享于帝立庙。",水泽节:"泽上有水，节。君子以制数度，议德行。",风泽中孚:"泽上有风，中孚。君子以议狱缓死。",雷山小过:"山上有雷，小过。君子以行过乎恭，丧过乎哀，用过乎俭。",水火既济:"水在火上，既济。君子以思患而豫防之。",火水未济:"火在水上，未济。君子以慎辨物居方。"},YAO_CI={乾为天初:"潜龙勿用",乾为天二:"见龙在田，利见大人",乾为天三:"君子终日乾乾，夕惕若厉，无咎",乾为天四:"或跃在渊，无咎",乾为天五:"飞龙在天，利见大人",乾为天上:"亢龙有悔",坤为地初:"履霜，坚冰至",坤为地二:"直方大，不习无不利",坤为地三:"含章可贞，或从王事，无成有终",坤为地四:"括囊，无咎无誉",坤为地五:"黄裳，元吉",坤为地上:"龙战于野，其血玄黄",水雷屯初:"磐桓，利居贞，利建侯",水雷屯二:"屯如邅如，乘马班如，匪寇婚媾，女子贞不字，十年乃字",水雷屯三:"即鹿无虞，惟入于林中，君子几，不如舍，往吝",水雷屯四:"乘马班如，求婚媾，往吉，无不利",水雷屯五:"屯其膏，小贞吉，大贞凶",水雷屯上:"乘马班如，泣血涟如",山水蒙初:"发蒙，利用刑人，用说桎梏，以往吝",山水蒙二:"包蒙吉，纳妇吉，子克家",山水蒙三:"勿用取女，见金夫，不有躬，无攸利",山水蒙四:"困蒙，吝",山水蒙五:"童蒙，吉",山水蒙上:"击蒙，不利为寇，利御寇",水天需初:"需于郊，利用恒，无咎",水天需二:"需于沙，小有言，终吉",水天需三:"需于泥，致寇至",水天需四:"需于血，出自穴",水天需五:"需于酒食，贞吉",水天需上:"入于穴，有不速之客三人来，敬之终吉",天水讼初:"不永所事，小有言，终吉",天水讼二:"不克讼，归而逋，其邑人三百户，无眚",天水讼三:"食旧德，贞厉，终吉，或从王事，无成",天水讼四:"不克讼，复即命，渝安贞吉",天水讼五:"讼，元吉",天水讼上:"或锡之鞶带，终朝三褫之",地水师初:"师出以律，否臧凶",地水师二:"在师中，吉无咎，王三锡命",地水师三:"师或舆尸，凶",地水师四:"师左次，无咎",地水师五:"田有禽，利执言，无咎，长子帅师，弟子舆尸，贞凶",地水师上:"大君有命，开国承家，小人勿用",水地比初:"有孚比之，无咎，有孚盈缶，终来有它，吉",水地比二:"比之自内，贞吉",水地比三:"比之匪人",水地比四:"外比之，贞吉",水地比五:"显比，王用三驱，失前禽，邑人不诫，吉",水地比上:"比之无首，凶",风天小畜初:"复自道，何其咎，吉",风天小畜二:"牵复，吉",风天小畜三:"舆说辐，夫妻反目",风天小畜四:"有孚，血去惕出，无咎",风天小畜五:"有孚挛如，富以其邻",风天小畜上:"既雨既处，尚德载，妇贞厉，月几望，君子征凶",天泽履初:"素履往，无咎",天泽履二:"履道坦坦，幽人贞吉",天泽履三:"眇能视，跛能履，履虎尾，咥人凶，武人为于大君",天泽履四:"履虎尾，愬愬终吉",天泽履五:"夬履，贞厉",天泽履上:"视履考祥，其旋元吉",地天泰初:"拔茅茹，以其汇，征吉",地天泰二:"包荒，用冯河，不遐遗，朋亡，得尚于中行",地天泰三:"无平不陂，无往不复，艰贞无咎，勿恤其孚，于食有福",地天泰四:"翩翩，不富以其邻，不戒以孚",地天泰五:"帝乙归妹，以祉元吉",地天泰上:"城复于隍，勿用师，自邑告命，贞吝",天地否初:"拔茅茹，以其汇，贞吉亨",天地否二:"包承，小人吉，大人否亨",天地否三:"包羞",天地否四:"有命无咎，畴离祉",天地否五:"休否，大人吉，其亡其亡，系于苞桑",天地否上:"倾否，先否后喜",天火同人初:"同人于门，无咎",天火同人二:"同人于宗，吝",天火同人三:"伏戎于莽，升其高陵，三岁不兴",天火同人四:"乘其墉，弗克攻，吉",天火同人五:"同人先号啕而后笑，大师克相遇",天火同人上:"同人于郊，无悔",火天大有初:"无交害，匪咎，艰则无咎",火天大有二:"大车以载，有攸往，无咎",火天大有三:"公用亨于天子，小人弗克",火天大有四:"匪其彭，无咎",火天大有五:"厥孚交如，威如，吉",火天大有上:"自天佑之，吉无不利",地山谦初:"谦谦君子，用涉大川，吉",地山谦二:"鸣谦，贞吉",地山谦三:"劳谦，君子有终，吉",地山谦四:"无不利，撝谦",地山谦五:"不富以其邻，利用侵伐，无不利",地山谦上:"鸣谦，利用行师，征邑国",雷地豫初:"鸣豫，凶",雷地豫二:"介于石，不终日，贞吉",雷地豫三:"盱豫悔，迟有悔",雷地豫四:"由豫，大有得，勿疑朋盍簪",雷地豫五:"贞疾，恒不死",雷地豫上:"冥豫，成有渝，无咎",泽雷随初:"官有渝，贞吉，出门交有功",泽雷随二:"系小子，失丈夫",泽雷随三:"系丈夫，失小子，随有求得，利居贞",泽雷随四:"随有获，贞凶，有孚在道，以明，何咎",泽雷随五:"孚于嘉，吉",泽雷随上:"拘系之，乃从维之，王用亨于西山",山风蛊初:"干父之蛊，有子考无咎，厉终吉",山风蛊二:"干母之蛊，不可贞",山风蛊三:"干父之蛊，小有悔，无大咎",山风蛊四:"裕父之蛊，往见吝",山风蛊五:"干父之蛊，用誉",山风蛊上:"不事王侯，高尚其事",地泽临初:"咸临，贞吉",地泽临二:"咸临，吉无不利",地泽临三:"甘临，无攸利，既忧之，无咎",地泽临四:"至临，无咎",地泽临五:"知临，大君之宜，吉",地泽临上:"敦临，吉无咎",风地观初:"童观，小人无咎，君子吝",风地观二:"窥观，利女贞",风地观三:"观我生，进退",风地观四:"观国之光，利用宾于王",风地观五:"观我生，君子无咎",风地观上:"观其生，君子无咎",火雷噬嗑初:"屦校灭趾，无咎",火雷噬嗑二:"噬肤灭鼻，无咎",火雷噬嗑三:"噬腊肉，遇毒，小吝，无咎",火雷噬嗑四:"噬干胏，得金矢，利艰贞，吉",火雷噬嗑五:"噬干肉，得黄金，贞厉，无咎",火雷噬嗑上:"何校灭耳，凶",山火贲初:"贲其趾，舍车而徒",山火贲二:"贲其须",山火贲三:"贲如濡如，永贞吉",山火贲四:"贲如皤如，白马翰如，匪寇婚媾",山火贲五:"贲于丘园，束帛戋戋，吝，终吉",山火贲上:"白贲，无咎",山地剥初:"剥床以足，蔑贞凶",山地剥二:"剥床以辨，蔑贞凶",山地剥三:"剥之，无咎",山地剥四:"剥床以肤，凶",山地剥五:"贯鱼，以宫人宠，无不利",山地剥上:"硕果不食，君子得舆，小人剥庐",地雷复初:"不远复，无祗悔，元吉",地雷复二:"休复，吉",地雷复三:"频复，厉无咎",地雷复四:"中行独复",地雷复五:"敦复，无悔",地雷复上:"迷复，凶，有灾眚，用行师，终有大败，以其国君凶，至于十年不克征",天雷无妄初:"无妄，往吉",天雷无妄二:"不耕获，不菑畬，则利有攸往",天雷无妄三:"无妄之灾，或系之牛，行人之得，邑人之灾",天雷无妄四:"可贞，无咎",天雷无妄五:"无妄之疾，勿药有喜",天雷无妄上:"无妄，行有眚，无攸利",山天大畜初:"有厉利已",山天大畜二:"舆说輹",山天大畜三:"良马逐，利艰贞，曰闲舆卫，利有攸往",山天大畜四:"童牛之牿，元吉",山天大畜五:"豮豕之牙，吉",山天大畜上:"何天之衢，亨",山雷颐初:"舍尔灵龟，观我朵颐，凶",山雷颐二:"颠颐，拂经，于丘颐，征凶",山雷颐三:"拂颐，贞凶，十年勿用，无攸利",山雷颐四:"颠颐吉，虎视眈眈，其欲逐逐，无咎",山雷颐五:"拂经，居贞吉，不可涉大川",山雷颐上:"由颐，厉吉，利涉大川",泽风大过初:"藉用白茅，无咎",泽风大过二:"枯杨生稊，老夫得其女妻，无不利",泽风大过三:"栋桡，凶",泽风大过四:"栋隆，吉，有它吝",泽风大过五:"枯杨生华，老妇得其士夫，无咎无誉",泽风大过上:"过涉灭顶，凶，无咎",坎为水初:"习坎，入于坎窞，凶",坎为水二:"坎有险，求小得",坎为水三:"来之坎坎，险且枕，入于坎窞，勿用",坎为水四:"樽酒簋贰，用缶，纳约自牖，终无咎",坎为水五:"坎不盈，祗既平，无咎",坎为水上:"系用徽纆，寘于丛棘，三岁不得，凶",离为火初:"履错然，敬之无咎",离为火二:"黄离，元吉",离为火三:"日昃之离，不鼓缶而歌，则大耋之嗟，凶",离为火四:"突如其来如，焚如，死如，弃如",离为火五:"出涕沱若，戚嗟若，吉",离为火上:"王用出征，有嘉折首，获匪其丑，无咎",泽山咸初:"咸其拇",泽山咸二:"咸其腓，凶，居吉",泽山咸三:"咸其股，执其随，往吝",泽山咸四:"贞吉悔亡，憧憧往来，朋从尔思",泽山咸五:"咸其脢，无悔",泽山咸上:"咸其辅颊舌",雷风恒初:"浚恒，贞凶，无攸利",雷风恒二:"悔亡",雷风恒三:"不恒其德，或承之羞，贞吝",雷风恒四:"田无禽",雷风恒五:"恒其德，贞，妇人吉，夫子凶",雷风恒上:"振恒，凶",天山遁初:"遁尾，厉，勿用有攸往",天山遁二:"执之用黄牛之革，莫之胜说",天山遁三:"系遁，有疾厉，畜臣妾吉",天山遁四:"好遁，君子吉，小人否",天山遁五:"嘉遁，贞吉",天山遁上:"肥遁，无不利",雷天大壮初:"壮于趾，征凶，有孚",雷天大壮二:"贞吉",雷天大壮三:"小人用壮，君子用罔，贞厉，羝羊触藩，羸其角",雷天大壮四:"贞吉悔亡，藩决不羸，壮于大舆之輹",雷天大壮五:"丧羊于易，无悔",雷天大壮上:"羝羊触藩，不能退，不能遂，无攸利，艰则吉",火地晋初:"晋如摧如，贞吉，罔孚，裕无咎",火地晋二:"晋如愁如，贞吉，受兹介福，于其王母",火地晋三:"众允，悔亡",火地晋四:"晋如鼫鼠，贞厉",火地晋五:"悔亡，失得勿恤，往吉，无不利",火地晋上:"晋其角，维用伐邑，厉吉无咎，贞吝",地火明夷初:"明夷于飞，垂其翼，君子于行，三日不食，有攸往，主人有言",地火明夷二:"明夷，夷于左股，用拯马壮，吉",地火明夷三:"明夷于南狩，得其大首，不可疾贞",地火明夷四:"入于左腹，获明夷之心，于出门庭",地火明夷五:"箕子之明夷，利贞",地火明夷上:"不明晦，初登于天，后入于地",风火家人初:"闲有家，悔亡",风火家人二:"无攸遂，在中馈，贞吉",风火家人三:"家人嗃嗃，悔厉吉，妇子嘻嘻，终吝",风火家人四:"富家，大吉",风火家人五:"王假有家，勿恤吉",风火家人上:"有孚威如，终吉",火泽睽初:"悔亡，丧马勿逐自复，见恶人无咎",火泽睽二:"遇主于巷，无咎",火泽睽三:"见舆曳，其牛掣，其人天且劓，无初有终",火泽睽四:"睽孤，遇元夫，交孚，厉无咎",火泽睽五:"悔亡，厥宗噬肤，往何咎",火泽睽上:"睽孤，见豕负涂，载鬼一车，先张之弧，后说之弧，匪寇婚媾，往遇雨则吉",水山蹇初:"往蹇来誉",水山蹇二:"王臣蹇蹇，匪躬之故",水山蹇三:"往蹇来反",水山蹇四:"往蹇来连",水山蹇五:"大蹇朋来",水山蹇上:"往蹇来硕，吉，利见大人",雷水解初:"无咎",雷水解二:"田获三狐，得黄矢，贞吉",雷水解三:"负且乘，致寇至，贞吝",雷水解四:"解而拇，朋至斯孚",雷水解五:"君子维有解，吉，有孚于小人",雷水解上:"公用射隼于高墉之上，获之，无不利",山泽损初:"已事遄往，无咎，酌损之",山泽损二:"利贞，征凶，弗损益之",山泽损三:"三人行，则损一人，一人行，则得其友",山泽损四:"损其疾，使遄有喜，无咎",山泽损五:"或益之十朋之龟，弗克违，元吉",山泽损上:"弗损益之，无咎，贞吉，利有攸往，得臣无家",风雷益初:"利用为大作，元吉，无咎",风雷益二:"或益之十朋之龟，弗克违，永贞吉，王用享于帝，吉",风雷益三:"益之用凶事，无咎，有孚中行，告公用圭",风雷益四:"中行告公从，利用为依迁国",风雷益五:"有孚惠心，勿问元吉，有孚惠我德",风雷益上:"莫益之，或击之，立心勿恒，凶",泽天夬初:"壮于前趾，往不胜为咎",泽天夬二:"惕号，莫夜有戎，勿恤",泽天夬三:"壮于頄，有凶，君子夬夬，独行遇雨，若濡有愠，无咎",泽天夬四:"臀无肤，其行次且，牵羊悔亡，闻言不信",泽天夬五:"苋陆夬夬，中行无咎",泽天夬上:"无号，终有凶",天风姤初:"系于金柅，贞吉，有攸往，见凶，羸豕孚蹢躅",天风姤二:"包有鱼，无咎，不利宾",天风姤三:"臀无肤，其行次且，厉，无大咎",天风姤四:"包无鱼，起凶",天风姤五:"以杞包瓜，含章，有陨自天",天风姤上:"姤其角，吝，无咎",泽地萃初:"有孚不终，乃乱乃萃，若号，一握为笑，勿恤，往无咎",泽地萃二:"引吉，无咎，孚乃利用禴",泽地萃三:"萃如嗟如，无攸利，往无咎，小吝",泽地萃四:"大吉，无咎",泽地萃五:"萃有位，无咎，匪孚，元永贞，悔亡",泽地萃上:"赍咨涕洟，无咎",地风升初:"允升，大吉",地风升二:"孚乃利用禴，无咎",地风升三:"升虚邑",地风升四:"王用亨于岐山，吉，无咎",地风升五:"贞吉，升阶",地风升上:"冥升，利于不息之贞",泽水困初:"臀困于株木，入于幽谷，三岁不觌",泽水困二:"困于酒食，朱绂方来，利用亨祀，征凶，无咎",泽水困三:"困于石，据于蒺藜，入于其宫，不见其妻，凶",泽水困四:"来徐徐，困于金车，吝，有终",泽水困五:"劓刖，困于赤绂，乃徐有说，利用祭祀",泽水困上:"困于葛藟，于臲卼，曰动悔有悔，征吉",水风井初:"井泥不食，旧井无禽",水风井二:"井谷射鲋，瓮敝漏",水风井三:"井渫不食，为我心恻，可用汲，王明并受其福",水风井四:"井甃，无咎",水风井五:"井冽寒泉，食",水风井上:"井收勿幕，有孚元吉",泽火革初:"巩用黄牛之革",泽火革二:"己日乃革之，征吉，无咎",泽火革三:"征凶，贞厉，革言三就，有孚",泽火革四:"悔亡，有孚改命，吉",泽火革五:"大人虎变，未占有孚",泽火革上:"君子豹变，小人革面，征凶，居贞吉",火风鼎初:"鼎颠趾，利出否，得妾以其子，无咎",火风鼎二:"鼎有实，我仇有疾，不我能即，吉",火风鼎三:"鼎耳革，其行塞，雉膏不食，方雨亏悔，终吉",火风鼎四:"鼎折足，覆公餗，其形渥，凶",火风鼎五:"鼎黄耳金铉，利贞",火风鼎上:"鼎玉铉，大吉，无不利",震为雷初:"震来虩虩，后笑言哑哑，吉",震为雷二:"震来厉，亿丧贝，跻于九陵，勿逐，七日得",震为雷三:"震苏苏，震行无眚",震为雷四:"震遂泥",震为雷五:"震往来厉，亿无丧，有事",震为雷上:"震索索，视矍矍，征凶，震不于其躬，于其邻，无咎，婚媾有言",艮为山初:"艮其趾，无咎，利永贞",艮为山二:"艮其腓，不拯其随，其心不快",艮为山三:"艮其限，列其夤，厉薰心",艮为山四:"艮其身，无咎",艮为山五:"艮其辅，言有序，悔亡",艮为山上:"敦艮，吉",风山渐初:"鸿渐于干，小子厉，有言，无咎",风山渐二:"鸿渐于磐，饮食衎衎，吉",风山渐三:"鸿渐于陆，夫征不复，妇孕不育，凶，利御寇",风山渐四:"鸿渐于木，或得其桷，无咎",风山渐五:"鸿渐于陵，妇三岁不孕，终莫之胜，吉",风山渐上:"鸿渐于陆，其羽可用为仪，吉",雷泽归妹初:"归妹以娣，跛能履，征吉",雷泽归妹二:"眇能视，利幽人之贞",雷泽归妹三:"归妹以须，反归以娣",雷泽归妹四:"归妹愆期，迟归有时",雷泽归妹五:"帝乙归妹，其君之袂，不如其娣之袂良，月几望，吉",雷泽归妹上:"女承筐无实，士刲羊无血，无攸利",雷火丰初:"遇其配主，虽旬无咎，往有尚",雷火丰二:"丰其蔀，日中见斗，往得疑疾，有孚发若，吉",雷火丰三:"丰其沛，日中见沫，折其右肱，无咎",雷火丰四:"丰其蔀，日中见斗，遇其夷主，吉",雷火丰五:"来章，有庆誉，吉",雷火丰上:"丰其屋，蔀其家，窥其户，阒其无人，三岁不觌，凶",火山旅初:"旅琐琐，斯其所取灾",火山旅二:"旅即次，怀其资，得童仆贞",火山旅三:"旅焚其次，丧其童仆，贞厉",火山旅四:"旅于处，得其资斧，我心不快",火山旅五:"射雉一矢亡，终以誉命",火山旅上:"鸟焚其巢，旅人先笑后号啕，丧牛于易，凶",巽为风初:"进退，利武人之贞",巽为风二:"巽在床下，用史巫纷若，吉，无咎",巽为风三:"频巽，吝",巽为风四:"悔亡，田获三品",巽为风五:"贞吉悔亡，无不利，无初有终，先庚三日，后庚三日，吉",巽为风上:"巽在床下，丧其资斧，贞凶",兑为泽初:"和兑，吉",兑为泽二:"孚兑，吉，悔亡",兑为泽三:"来兑，凶",兑为泽四:"商兑未宁，介疾有喜",兑为泽五:"孚于剥，有厉",兑为泽上:"引兑",风水涣初:"用拯马壮，吉",风水涣二:"涣奔其机，悔亡",风水涣三:"涣其躬，无悔",风水涣四:"涣其群，元吉，涣有丘，匪夷所思",风水涣五:"涣汗其大号，涣王居，无咎",风水涣上:"涣其血去逖出，无咎",水泽节初:"不出户庭，无咎",水泽节二:"不出门庭，凶",水泽节三:"不节若，则嗟若，无咎",水泽节四:"安节，亨",水泽节五:"甘节，吉，往有尚",水泽节上:"苦节，贞凶，悔亡",风泽中孚初:"虞吉，有它不燕",风泽中孚二:"鸣鹤在阴，其子和之，我有好爵，吾与尔靡之",风泽中孚三:"得敌，或鼓或罢，或泣或歌",风泽中孚四:"月几望，马匹亡，无咎",风泽中孚五:"有孚挛如，无咎",风泽中孚上:"翰音登于天，贞凶",雷山小过初:"飞鸟以凶",雷山小过二:"过其祖，遇其妣，不及其君，遇其臣，无咎",雷山小过三:"弗过防之，从或戕之，凶",雷山小过四:"无咎，弗过遇之，往厉必戒，勿用永贞",雷山小过五:"密云不雨，自我西郊，公弋取彼在穴",雷山小过上:"弗遇过之，飞鸟离之，凶，是谓灾眚",水火既济初:"曳其轮，濡其尾，无咎",水火既济二:"妇丧其茀，勿逐，七日得",水火既济三:"高宗伐鬼方，三年克之，小人勿用",水火既济四:"繻有衣袽，终日戒",水火既济五:"东邻杀牛，不如西邻之禴祭，实受其福",水火既济上:"濡其首，厉",火水未济初:"濡其尾，吝",火水未济二:"曳其轮，贞吉",火水未济三:"未济，征凶，利涉大川",火水未济四:"贞吉悔亡，震用伐鬼方，三年有赏于大国",火水未济五:"贞吉无悔，君子之光，有孚吉",火水未济上:"有孚于饮酒，无咎，濡其首，有孚失是"},YAO_XIAOXIANG={乾为天初:"潜龙勿用，阳在下也",乾为天二:"见龙在田，德施普也",乾为天三:"终日乾乾，反复道也",乾为天四:"或跃在渊，进无咎也",乾为天五:"飞龙在天，大人造也",乾为天上:"亢龙有悔，盈不可久也",坤为地初:"履霜坚冰，阴始凝也，驯致其道，至坚冰也",坤为地二:"六二之动，直以方也，不习无不利，地道光也",坤为地三:"含章可贞，以时发也，或从王事，知光大也",坤为地四:"括囊无咎，慎不害也",坤为地五:"黄裳元吉，文在中也",坤为地上:"龙战于野，其道穷也",水雷屯初:"虽磐桓，志行正也，以贵下贱，大得民也",水雷屯二:"六二之难，乘刚也，十年乃字，反常也",水雷屯三:"即鹿无虞，以从禽也，君子舍之，往吝穷也",水雷屯四:"求而往，明也",水雷屯五:"屯其膏，施未光也",水雷屯上:"泣血涟如，何可长也",山水蒙初:"利用刑人，以正法也",山水蒙二:"子克家，刚柔接也",山水蒙三:"勿用取女，行不顺也",山水蒙四:"困蒙之吝，独远实也",山水蒙五:"童蒙之吉，顺以巽也",山水蒙上:"利用御寇，上下顺也",水天需初:"需于郊，不犯难行也，利用恒无咎，未失常也",水天需二:"需于沙，衍在中也，虽小有言，以吉终也",水天需三:"需于泥，灾在外也，自我致寇，敬慎不败也",水天需四:"需于血，顺以听也",水天需五:"酒食贞吉，以中正也",水天需上:"不速之客来，敬之终吉，虽不当位，未大失也",天水讼初:"不永所事，讼不可长也，虽小有言，其辩明也",天水讼二:"不克讼归逋，窜也，自下讼上，患至掇也",天水讼三:"食旧德，从上吉也",天水讼四:"复即命渝，安贞不失也",天水讼五:"讼元吉，以中正也",天水讼上:"以讼受服，亦不足敬也",地水师初:"师出以律，失律凶也",地水师二:"在师中吉，承天宠也，王三锡命，怀万邦也",地水师三:"师或舆尸，大无功也",地水师四:"左次无咎，未失常也",地水师五:"长子帅师，以中行也，弟子舆尸，使不当也",地水师上:"大君有命，以正功也，小人勿用，必乱邦也",水地比初:"比之初六，有它吉也",水地比二:"比之自内，不自失也",水地比三:"比之匪人，不亦伤乎",水地比四:"外比于贤，以从上也",水地比五:"显比之吉，位正中也，舍逆取顺，失前禽也，邑人不诫，上使中也",水地比上:"比之无首，无所终也",风天小畜初:"复自道，其义吉也",风天小畜二:"牵复在中，亦不自失也",风天小畜三:"夫妻反目，不能正室也",风天小畜四:"有孚惕出，上合志也",风天小畜五:"有孚挛如，不独富也",风天小畜上:"既雨既处，德积载也，君子征凶，有所疑也",天泽履初:"素履之往，独行愿也",天泽履二:"幽人贞吉，中不自乱也",天泽履三:"眇能视，跛能履，不足以有明也，咥人之凶，位不当也，武人为于大君，志刚也",天泽履四:"愬愬终吉，志行也",天泽履五:"夬履贞厉，位正当也",天泽履上:"元吉在上，大有庆也",地天泰初:"拔茅征吉，志在外也",地天泰二:"包荒得尚于中行，以光大也",地天泰三:"无往不复，天地际也",地天泰四:"翩翩不富，皆失实也，不戒以孚，中心愿也",地天泰五:"以祉元吉，中以行愿也",地天泰上:"城复于隍，其命乱也",天地否初:"拔茅贞吉，志在君也",天地否二:"大人否亨，不乱群也",天地否三:"包羞，位不当也",天地否四:"有命无咎，志行也",天地否五:"大人之吉，位正当也",天地否上:"否终则倾，何可长也",天火同人初:"出门同人，又谁咎也",天火同人二:"同人于宗，吝道也",天火同人三:"伏戎于莽，敌刚也，三岁不兴，安行也",天火同人四:"乘其墉，义弗克也，其吉则困而反则也",天火同人五:"同人之先，以中直也，大师相遇，言相克也",天火同人上:"同人于郊，志未得也",火天大有初:"大有初九，无交害也",火天大有二:"大车以载，积中不败也",火天大有三:"公用亨于天子，小人害也",火天大有四:"匪其彭无咎，明辨晳也",火天大有五:"厥孚交如，信以发志也，威如之吉，易而无备也",火天大有上:"大有上吉，自天佑也",地山谦初:"谦谦君子，卑以自牧也",地山谦二:"鸣谦贞吉，中心得也",地山谦三:"劳谦君子，万民服也",地山谦四:"无不利撝谦，不违则也",地山谦五:"利用侵伐，征不服也",地山谦上:"鸣谦，志未得也，可用行师，征邑国也",雷地豫初:"初六鸣豫，志穷凶也",雷地豫二:"不终日贞吉，以中正也",雷地豫三:"盱豫有悔，位不当也",雷地豫四:"由豫大有得，志大行也",雷地豫五:"六五贞疾，乘刚也，恒不死，中未亡也",雷地豫上:"冥豫在上，何可长也",泽雷随初:"官有渝，从正吉也，出门交有功，不失也",泽雷随二:"系小子，弗兼与也",泽雷随三:"系丈夫，志舍下也",泽雷随四:"随有获，其义凶也，有孚在道，明功也",泽雷随五:"孚于嘉吉，位正中也",泽雷随上:"拘系之，上穷也",山风蛊初:"干父之蛊，意承考也",山风蛊二:"干母之蛊，得中道也",山风蛊三:"干父之蛊，终无咎也",山风蛊四:"裕父之蛊，往未得也",山风蛊五:"干父用誉，承以德也",山风蛊上:"不事王侯，志可则也",地泽临初:"咸临贞吉，志行正也",地泽临二:"咸临吉无不利，未顺命也",地泽临三:"甘临，位不当也，既忧之，咎不长也",地泽临四:"至临无咎，位当也",地泽临五:"大君之宜，行中之谓也",地泽临上:"敦临之吉，志在内也",风地观初:"初六童观，小人道也",风地观二:"窥观女贞，亦可丑也",风地观三:"观我生进退，未失道也",风地观四:"观国之光，尚宾也",风地观五:"观我生，观民也",风地观上:"观其生，志未平也",火雷噬嗑初:"屦校灭趾，不行也",火雷噬嗑二:"噬肤灭鼻，乘刚也",火雷噬嗑三:"遇毒，位不当也",火雷噬嗑四:"利艰贞吉，未光也",火雷噬嗑五:"贞厉无咎，得当也",火雷噬嗑上:"何校灭耳，聪不明也",山火贲初:"舍车而徒，义弗乘也",山火贲二:"贲其须，与上兴也",山火贲三:"永贞之吉，终莫之陵也",山火贲四:"六四当位，疑也，匪寇婚媾，终无尤也",山火贲五:"六五之吉，有喜也",山火贲上:"白贲无咎，上得志也",山地剥初:"剥床以足，以灭下也",山地剥二:"剥床以辨，未有与也",山地剥三:"剥之无咎，失上下也",山地剥四:"剥床以肤，切近灾也",山地剥五:"以宫人宠，终无尤也",山地剥上:"君子得舆，民所载也，小人剥庐，终不可用也",地雷复初:"不远之复，以修身也",地雷复二:"休复之吉，以下仁也",地雷复三:"频复之厉，义无咎也",地雷复四:"中行独复，以从道也",地雷复五:"敦复无悔，中以自考也",地雷复上:"迷复之凶，反君道也",天雷无妄初:"无妄之往，得志也",天雷无妄二:"不耕获，未富也",天雷无妄三:"行人得牛，邑人灾也",天雷无妄四:"可贞无咎，固有之也",天雷无妄五:"无妄之药，不可试也",天雷无妄上:"无妄之行，穷之灾也",山天大畜初:"有厉利已，不犯灾也",山天大畜二:"舆说輹，中无尤也",山天大畜三:"利有攸往，上合志也",山天大畜四:"六四元吉，有喜也",山天大畜五:"六五之吉，有庆也",山天大畜上:"何天之衢，道大行也",山雷颐初:"观我朵颐，亦不足贵也",山雷颐二:"六二征凶，行失类也",山雷颐三:"十年勿用，道大悖也",山雷颐四:"颠颐之吉，上施光也",山雷颐五:"居贞之吉，顺以从上也",山雷颐上:"由颐厉吉，大有庆也",泽风大过初:"藉用白茅，柔在下也",泽风大过二:"老夫女妻，过以相与也",泽风大过三:"栋桡之凶，不可以有辅也",泽风大过四:"栋隆之吉，不桡乎下也",泽风大过五:"枯杨生华，何可久也，老妇士夫，亦可丑也",泽风大过上:"过涉之凶，不可咎也",坎为水初:"习坎入坎，失道凶也",坎为水二:"求小得，未出中也",坎为水三:"来之坎坎，终无功也",坎为水四:"樽酒簋贰，刚柔际也",坎为水五:"坎不盈，中未大也",坎为水上:"上六失道，凶三岁也",离为火初:"履错之敬，以辟咎也",离为火二:"黄离元吉，得中道也",离为火三:"日昃之离，何可久也",离为火四:"突如其来如，无所容也",离为火五:"六五之吉，离王公也",离为火上:"王用出征，以正邦也",泽山咸初:"咸其拇，志在外也",泽山咸二:"虽凶居吉，顺不害也",泽山咸三:"咸其股，亦不处也，志在随人，所执下也",泽山咸四:"贞吉悔亡，未感害也，憧憧往来，未光大也",泽山咸五:"咸其脢，志末也",泽山咸上:"咸其辅颊舌，滕口说也",雷风恒初:"浚恒之凶，始求深也",雷风恒二:"九二悔亡，能久中也",雷风恒三:"不恒其德，无所容也",雷风恒四:"久非其位，安得禽也",雷风恒五:"妇人贞吉，从一而终也，夫子制义，从妇凶也",雷风恒上:"振恒在上，大无功也",天山遁初:"遁尾之厉，不往何灾也",天山遁二:"执用黄牛，固志也",天山遁三:"系遁之厉，有疾惫也，畜臣妾吉，不可大事也",天山遁四:"君子好遁，小人否也",天山遁五:"嘉遁贞吉，以正志也",天山遁上:"肥遁无不利，无所疑也",雷天大壮初:"壮于趾，其孚穷也",雷天大壮二:"九二贞吉，以中也",雷天大壮三:"小人用壮，君子罔也",雷天大壮四:"藩决不羸，尚往也",雷天大壮五:"丧羊于易，位不当也",雷天大壮上:"不能退，不能遂，不详也，艰则吉，咎不长也",火地晋初:"晋如摧如，独行正也，裕无咎，未受命也",火地晋二:"受兹介福，以中正也",火地晋三:"众允之，志上行也",火地晋四:"鼫鼠贞厉，位不当也",火地晋五:"失得勿恤，往有庆也",火地晋上:"维用伐邑，道未光也",地火明夷初:"君子于行，义不食也",地火明夷二:"六二之吉，顺以则也",地火明夷三:"南狩之志，乃大得也",地火明夷四:"入于左腹，获心意也",地火明夷五:"箕子之贞，明不可息也",地火明夷上:"初登于天，照四国也，后入于地，失则也",风火家人初:"闲有家，志未变也",风火家人二:"六二之吉，顺以巽也",风火家人三:"家人嗃嗃，未失也，妇子嘻嘻，失家节也",风火家人四:"富家大吉，顺在位也",风火家人五:"王假有家，交相爱也",风火家人上:"威如之吉，反身之谓也",火泽睽初:"见恶人，以辟咎也",火泽睽二:"遇主于巷，未失道也",火泽睽三:"见舆曳，位不当也，无初有终，遇刚也",火泽睽四:"交孚无咎，志行也",火泽睽五:"厥宗噬肤，往有庆也",火泽睽上:"遇雨之吉，群疑亡也",水山蹇初:"往蹇来誉，宜待也",水山蹇二:"王臣蹇蹇，终无尤也",水山蹇三:"往蹇来反，内喜之也",水山蹇四:"往蹇来连，当位实也",水山蹇五:"大蹇朋来，以中节也",水山蹇上:"往蹇来硕，志在内也，利见大人，以从贵也",雷水解初:"刚柔之际，义无咎也",雷水解二:"九二贞吉，得中道也",雷水解三:"负且乘，亦可丑也，自我致戎，又谁咎也",雷水解四:"解而拇，未当位也",雷水解五:"君子有解，小人退也",雷水解上:"公用射隼，以解悖也",山泽损初:"已事遄往，尚合志也",山泽损二:"九二利贞，中以为志也",山泽损三:"一人行，三则疑也",山泽损四:"损其疾，亦可喜也",山泽损五:"六五元吉，自上佑也",山泽损上:"弗损益之，大得志也",风雷益初:"元吉无咎，下不厚事也",风雷益二:"或益之，自外来也",风雷益三:"益用凶事，固有之也",风雷益四:"告公从，以益志也",风雷益五:"有孚惠心，勿问之矣，惠我德，大得志也",风雷益上:"莫益之，偏辞也，或击之，自外来也",泽天夬初:"不胜而往，咎也",泽天夬二:"有戎勿恤，得中道也",泽天夬三:"君子夬夬，终无咎也",泽天夬四:"其行次且，位不当也，闻言不信，聪不明也",泽天夬五:"中行无咎，中未光也",泽天夬上:"无号之凶，终不可长也",天风姤初:"系于金柅，柔道牵也",天风姤二:"包有鱼，义不及宾也",天风姤三:"其行次且，行未牵也",天风姤四:"无鱼之凶，远民也",天风姤五:"九五含章，中正也，有陨自天，志不舍命也",天风姤上:"姤其角，上穷吝也",泽地萃初:"乃乱乃萃，其志乱也",泽地萃二:"引吉无咎，中未变也",泽地萃三:"往无咎，上巽也",泽地萃四:"大吉无咎，位不当也",泽地萃五:"萃有位，志未光也",泽地萃上:"赍咨涕洟，未安上也",地风升初:"允升大吉，上合志也",地风升二:"九二之孚，有喜也",地风升三:"升虚邑，无所疑也",地风升四:"王用亨于岐山，顺事也",地风升五:"贞吉升阶，大得志也",地风升上:"冥升在上，消不富也",泽水困初:"入于幽谷，幽不明也",泽水困二:"困于酒食，中有庆也",泽水困三:"据于蒺藜，乘刚也，入于其宫，不见其妻，不祥也",泽水困四:"来徐徐，志在下也，虽不当位，有与也",泽水困五:"劓刖，志未得也，乃徐有说，以中直也，利用祭祀，受福也",泽水困上:"困于葛藟，未当也，动悔有悔，吉行也",水风井初:"井泥不食，下也，旧井无禽，时舍也",水风井二:"井谷射鲋，无与也",水风井三:"井渫不食，行恻也，求王明，受福也",水风井四:"井甃无咎，修井也",水风井五:"寒泉之食，中正也",水风井上:"元吉在上，大成也",泽火革初:"巩用黄牛，不可以有为也",泽火革二:"己日革之，行有嘉也",泽火革三:"革言三就，又何之矣",泽火革四:"改命之吉，信志也",泽火革五:"大人虎变，其文炳也",泽火革上:"君子豹变，其文蔚也，小人革面，顺以从君也",火风鼎初:"鼎颠趾，未悖也，利出否，以从贵也",火风鼎二:"鼎有实，慎所之也，我仇有疾，终无尤也",火风鼎三:"鼎耳革，失其义也",火风鼎四:"覆公餗，信如何也",火风鼎五:"鼎黄耳，中以为实也",火风鼎上:"玉铉在上，刚柔节也",震为雷初:"震来虩虩，恐致福也，笑言哑哑，后有则也",震为雷二:"震来厉，乘刚也",震为雷三:"震苏苏，位不当也",震为雷四:"震遂泥，未光也",震为雷五:"震往来厉，危行也，其事在中，大无丧也",震为雷上:"震索索，中未得也，虽凶无咎，畏邻戒也",艮为山初:"艮其趾，未失正也",艮为山二:"不拯其随，未退听也",艮为山三:"艮其限，危薰心也",艮为山四:"艮其身，止诸躬也",艮为山五:"艮其辅，以中正也",艮为山上:"敦艮之吉，以厚终也",风山渐初:"小子之厉，义无咎也",风山渐二:"饮食衎衎，不素饱也",风山渐三:"夫征不复，离群丑也，妇孕不育，失其道也，利用御寇，顺相保也",风山渐四:"或得其桷，顺以巽也",风山渐五:"终莫之胜吉，得所愿也",风山渐上:"其羽可用为仪吉，不可乱也",雷泽归妹初:"归妹以娣，以恒也，跛能履吉，相承也",雷泽归妹二:"利幽人之贞，未变常也",雷泽归妹三:"归妹以须，未当也",雷泽归妹四:"愆期之志，有待而行也",雷泽归妹五:"帝乙归妹，不如其娣之袂良也，其位在中，以贵行也",雷泽归妹上:"上六无实，承虚筐也",雷火丰初:"虽旬无咎，过旬灾也",雷火丰二:"有孚发若，信以发志也",雷火丰三:"丰其沛，不可大事也，折其右肱，终不可用也",雷火丰四:"丰其蔀，位不当也，日中见斗，幽不明也，遇其夷主，吉行也",雷火丰五:"六五之吉，有庆也",雷火丰上:"丰其屋，天际翔也，窥其户，阒其无人，自藏也",火山旅初:"旅琐琐，志穷灾也",火山旅二:"得童仆贞，终无尤也",火山旅三:"旅焚其次，亦以伤矣，以旅与下，其义丧也",火山旅四:"旅于处，未得位也，得其资斧，心未快也",火山旅五:"终以誉命，上逮也",火山旅上:"以旅在上，其义焚也，丧牛于易，终莫之闻也",巽为风初:"进退，志疑也，利武人之贞，志治也",巽为风二:"纷若之吉，得中也",巽为风三:"频巽之吝，志穷也",巽为风四:"田获三品，有功也",巽为风五:"九五之吉，位正中也",巽为风上:"巽在床下，上穷也，丧其资斧，正乎凶也",兑为泽初:"和兑之吉，行未疑也",兑为泽二:"孚兑之吉，信志也",兑为泽三:"来兑之凶，位不当也",兑为泽四:"九四之喜，有庆也",兑为泽五:"孚于剥，位正当也",兑为泽上:"上六引兑，未光也",风水涣初:"初六之吉，顺也",风水涣二:"涣奔其机，得愿也",风水涣三:"涣其躬，志在外也",风水涣四:"涣其群元吉，光大也",风水涣五:"王居无咎，正位也",风水涣上:"涣其血，远害也",水泽节初:"不出户庭，知通塞也",水泽节二:"不出门庭凶，失时极也",水泽节三:"不节之嗟，又谁咎也",水泽节四:"安节之亨，承上道也",水泽节五:"甘节之吉，居位中也",水泽节上:"苦节贞凶，其道穷也",风泽中孚初:"初九虞吉，志未变也",风泽中孚二:"其子和之，中心愿也",风泽中孚三:"或鼓或罢，位不当也",风泽中孚四:"马匹亡，绝类上也",风泽中孚五:"有孚挛如，位正当也",风泽中孚上:"翰音登于天，何可长也",雷山小过初:"飞鸟以凶，不可如何也",雷山小过二:"不及其君，臣不可过也",雷山小过三:"从或戕之，凶如何也",雷山小过四:"弗过遇之，位不当也，往厉必戒，终不可长也",雷山小过五:"密云不雨，已上也",雷山小过上:"弗遇过之，已亢也",水火既济初:"曳其轮，义无咎也",水火既济二:"七日得，以中道也",水火既济三:"三年克之，惫也",水火既济四:"终日戒，有所疑也",水火既济五:"东邻杀牛，不如西邻之时也，实受其福，吉大来也",水火既济上:"濡其首厉，何可久也",火水未济初:"濡其尾，亦不知极也",火水未济二:"九二贞吉，中以行正也",火水未济三:"未济征凶，位不当也",火水未济四:"贞吉悔亡，志行也",火水未济五:"君子之光，其晖吉也",火水未济上:"饮酒濡首，亦不知节也"};

